const people = [
  {name: 'Alice', dept: 'eng'},
  {name: 'Bob', dept: 'sales'},
  {name: 'Charlie', dept: 'eng'}
];
const grouped = people.reduce((acc, p) => {
  acc[p.dept] = acc[p.dept] || [];
  acc[p.dept].push(p.name);
  return acc;
}, {});
console.log(grouped);
